    /// <summary>True for path data, false for a single Segoe Fluent Icons character.</summary>
    public static bool IsPath(string glyph) => glyph.Length > 2;

    /// <summary>An icon for menus and app bar buttons; a path icon follows the text colour like a font icon.</summary>
    public static IconElement Make(string glyph, double size = 20) => IsPath(glyph)
        ? new PathIcon { Data = Geometry(glyph), Width = size, Height = size, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center }
        : new FontIcon { Glyph = glyph, FontSize = size };

    /// <summary>For buttons and rows that take any element: a path icon is drawn on its 20 grid and scaled to the size.</summary>
    public static FrameworkElement Element(string glyph, double size) => IsPath(glyph)
        ? new Viewbox { Width = size, Height = size, Child = Make(glyph) }
        : new FontIcon { Glyph = glyph, FontSize = size };

    // Each icon gets its own geometry: WinUI does not let two elements share one.
    public static Geometry Geometry(string data) => (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), data);
}
